   for(nZero=0; nZero<nDigit && p->a[nZero]==0; nZero++){}
+  N += nZero;
   nFrac = p->nFrac + (nDigit - p->nDigit);
   nDigit -= nZero;
   z = sqlite3_malloc64( (sqlite3_int64)nDigit+20 );
   if( z==0 ){
     sqlite3_result_error_nomem(pCtx);
@@ -675,14 +701,20 @@ static void decimalFunc(
